#!/usr/bin/env python3
"""CZU-MHAD INERTIAL published-baseline: statistical-moment features + CRC on RAW accel+gyro.

Mirror of crc_baseline.py (CZU) but on the inertial modality (sensor_mat), reproducing the
CZU-MHAD paper's inertial recognizer family (Chao et al. 2022): per-channel statistical moments
(mean/std/var/skew/kurtosis) of the 10x6 raw signals + CRC-RLS (lambda=1e-4). Applied on the
BYTE-IDENTICAL LOSO k-shot splits generated by the deep CZU-IMU run, giving a same-splits
head-to-head "hand-crafted inertial + CRC vs NTU-pretrained encoder on IMU". This baseline is
robust to any frame-alignment issues in the derived quats (it uses raw accel+gyro directly), so
it yields a result even if the deep cross-modal transfer degrades.

Outputs -> trained_models/CZU-IMU-LOSO/crc_baseline/
"""
import os, json, glob, re
import numpy as np
import pandas as pd
import scipy.io as sio

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))))
SENSOR_DIR = os.path.join(ROOT, "external_data/czu_mhad_data/CZU-MHAD/sensor_mat")
RUN = os.path.join(ROOT, "trained_models/CZU-IMU-LOSO")
SPLITS = os.path.join(RUN, "splits")
OUT = os.path.join(RUN, "crc_baseline")
SUBJECTS = ["cx", "cyy", "myj", "qyh", "zyh"]
KS = [0, 1, 3]
LAMBDA = 1e-4
NAME_RE = re.compile(r"([a-z]+)__a(\d+)__t(\d+)")

try:
    from scipy.stats import skew, kurtosis
    HAVE_SCIPY = True
except Exception:
    HAVE_SCIPY = False


def npy_to_mat(npy_name):
    """cx__a10__t01.npy -> sensor_mat/cx_a10_t1.mat"""
    m = NAME_RE.match(npy_name.replace(".npy", ""))
    subj, aid, rep = m.group(1), int(m.group(2)), int(m.group(3))
    return os.path.join(SENSOR_DIR, f"{subj}_a{aid}_t{rep}.mat"), f"a{aid:02d}"


def clip_features(npy_name):
    """10 sensors x 6 channels (accel+gyro) -> 10*6*5 statistical-moment vector.
    Moments over time per channel; timestamp column dropped. Length-invariant."""
    mat_path, _ = npy_to_mat(npy_name)
    sensor = sio.loadmat(mat_path)["sensor"]              # (10,1) object
    feats = []
    for i in range(sensor.shape[0]):
        a = sensor[i, 0][:, :6].astype(np.float64)        # (F,6) accel+gyro
        mean = a.mean(0); std = a.std(0); var = a.var(0)
        if HAVE_SCIPY:
            sk = skew(a, axis=0, bias=False); ku = kurtosis(a, axis=0, bias=False)
        else:
            c = a - mean; s = np.where(std > 1e-8, std, 1.0)
            sk = (c ** 3).mean(0) / s ** 3
            ku = (c ** 4).mean(0) / s ** 4 - 3.0
        feats.append(np.concatenate([mean, std, var, sk, ku]))
    f = np.concatenate(feats)
    return np.nan_to_num(f, nan=0.0, posinf=0.0, neginf=0.0)


def crc_predict(Xtr, ytr, Xte, lam=LAMBDA):
    d, N = Xtr.shape
    G = Xtr.T @ Xtr + lam * np.eye(N)
    Proj = np.linalg.solve(G, Xtr.T)
    Coef = Proj @ Xte
    classes = np.unique(ytr)
    M = Xte.shape[1]
    res = np.full((len(classes), M), np.inf)
    for ci, c in enumerate(classes):
        mm = ytr == c
        Xc = Xtr[:, mm]; Cc = Coef[mm]
        recon = Xc @ Cc
        num = np.linalg.norm(Xte - recon, axis=0)
        den = np.linalg.norm(Cc, axis=0) + 1e-12
        res[ci] = num / den
    return classes[np.argmin(res, axis=0)]


def macro_f1(y_true, y_pred, classes):
    f1s = []
    for c in classes:
        tp = np.sum((y_pred == c) & (y_true == c))
        fp = np.sum((y_pred == c) & (y_true != c))
        fn = np.sum((y_pred != c) & (y_true == c))
        p = tp / (tp + fp) if tp + fp else 0.0
        r = tp / (tp + fn) if tp + fn else 0.0
        f1s.append(2 * p * r / (p + r) if p + r else 0.0)
    return float(np.mean(f1s))


def main():
    os.makedirs(OUT, exist_ok=True)
    print(f"scipy moments: {HAVE_SCIPY}")
    # cache features for every clip referenced in any split
    all_names = set()
    for k in KS:
        for s in SUBJECTS:
            sp = json.load(open(os.path.join(SPLITS, f"{s}_k{k}_calibration_split.json")))
            all_names.update(sp["calib_files"]); all_names.update(sp["eval_files"])
    feat = {fn: clip_features(fn) for fn in sorted(all_names)}
    lab = {fn: NAME_RE.match(fn.replace(".npy", "")).group(2) for fn in all_names}
    lab = {fn: f"a{int(v):02d}" for fn, v in lab.items()}
    classes = np.array(sorted(set(lab.values())))
    print(f"{len(all_names)} clips, {len(classes)} classes, feat-dim {len(next(iter(feat.values())))}")

    rows = []
    for k in KS:
        for s in SUBJECTS:
            sp = json.load(open(os.path.join(SPLITS, f"{s}_k{k}_calibration_split.json")))
            calib = sp["calib_files"]; ev = sp["eval_files"]
            # dictionary = all clips of the other 4 subjects + k-shot calib clips of held-out.
            # other-subject clips = every split filename not belonging to s (union of eval sets
            # across the k=0 fold gives all of s's clips; other subjects' clips come from their folds)
            train_files = sorted({fn for fn in feat if fn.split("__")[0] != s}) + list(calib)
            Xtr = np.stack([feat[fn] for fn in train_files]).T
            ytr = np.array([lab[fn] for fn in train_files])
            Xte = np.stack([feat[fn] for fn in ev]).T
            yte = np.array([lab[fn] for fn in ev])
            mu = Xtr.mean(1, keepdims=True); sd = Xtr.std(1, keepdims=True) + 1e-8
            Xtr = (Xtr - mu) / sd; Xte = (Xte - mu) / sd
            Xtr /= (np.linalg.norm(Xtr, axis=0, keepdims=True) + 1e-12)
            Xte /= (np.linalg.norm(Xte, axis=0, keepdims=True) + 1e-12)
            pred = crc_predict(Xtr, ytr, Xte)
            acc = float((pred == yte).mean()) * 100
            f1 = macro_f1(yte, pred, classes)
            rows.append(dict(test_subject=s, k=k, n_train=len(train_files),
                             eval_samples=len(ev), acc=round(acc, 3), macro_f1=round(f1, 4)))
            print(f"  k={k} subj={s}: acc={acc:.2f} (train {len(train_files)}, eval {len(ev)})")
    pf = pd.DataFrame(rows)
    pf.to_csv(os.path.join(OUT, "crc_per_fold.csv"), index=False)

    summ = pf.groupby("k").agg(crc_acc=("acc", "mean"), crc_acc_sd=("acc", "std"),
                               crc_macro_f1=("macro_f1", "mean")).round(3).reset_index()
    summ.to_csv(os.path.join(OUT, "crc_summary.csv"), index=False)
    print("\nCRC inertial baseline (mean over 5 LOSO folds):")
    print(summ.to_string(index=False))

    rec = pd.read_csv(os.path.join(RUN, "summary.csv"))
    rec_mean = rec.groupby(["method", "k"]).final_acc.mean().reset_index()
    comp = summ[["k", "crc_acc"]].copy()
    for m in ["scratch", "mae", "supMAE", "supLP120"]:
        sub = rec_mean[rec_mean.method == m].set_index("k").final_acc
        comp[m] = comp.k.map(sub.round(2))
    comp = comp.rename(columns={"crc_acc": "CRC_baseline"})
    comp.to_csv(os.path.join(OUT, "comparison.csv"), index=False)
    print("\nComparison — CRC inertial vs learned recognizer (mean acc over 5 folds):")
    print(comp.to_string(index=False))
    print(f"\nWrote -> {OUT}")


if __name__ == "__main__":
    main()
